#include <limits>
#include <iostream>

int main() {
    using T = float;
    std::cout << "--- Float Limits ---\n";
    std::cout << "IEC 559 Compliant: " << std::numeric_limits<T>::is_iec559 << "\n";

    if (std::numeric_limits<T>::has_quiet_NaN) {
        T qnan = std::numeric_limits<T>::quiet_NaN();
        std::cout << "Quiet NaN available: " << qnan << "\n";
    } else {
        std::cout << "Quiet NaN not supported.\n";
    }

    std::cout << "Denormal support: " << static_cast<int>(std::numeric_limits<T>::has_denorm) << " (1=yes, 2=indeterminate)\n";
}
